"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["646"],{3036(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>r,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"ai-usage","title":"AI usage","description":"fuegocable aims to be a reliable source of knowledge and provide a solid, stable hardware and software solution for modifying audio interfaces. We\u2019re not there yet, but LLMs can help us achieve this goal. First and foremost, by making technical information more accessible, finding datasheets, and helping us understand complex concepts. And, of course, by generating code. Above all, however, we will always prioritize human judgment and good taste, whether in documentation, images, or code structure.","source":"@site/docs/ai-usage.mdx","sourceDirName":".","slug":"/ai-usage","permalink":"/docs/ai-usage","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":6,"frontMatter":{"sidebar_position":6},"sidebar":"tutorialSidebar","previous":{"title":"Testing & bug reports","permalink":"/docs/how-to-contribute/testing-bug-reports"}}'),a=n(4848),s=n(8453);let o={sidebar_position:6},r="AI usage",l={},d=[];function c(e){let t={em:"em",h1:"h1",header:"header",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"ai-usage",children:"AI usage"})}),"\n",(0,a.jsx)(t.p,{children:"fuegocable aims to be a reliable source of knowledge and provide a solid, stable hardware and software solution for modifying audio interfaces. We\u2019re not there yet, but LLMs can help us achieve this goal. First and foremost, by making technical information more accessible, finding datasheets, and helping us understand complex concepts. And, of course, by generating code. Above all, however, we will always prioritize human judgment and good taste, whether in documentation, images, or code structure."}),"\n",(0,a.jsx)(t.p,{children:"At the moment (2026), the use of generative AI in the project is quite limited. The documentation was written by a human, as was practically all of the firmware code. This does not necessarily mean it will always be that way. Translations to english and code-review were done with help of LLMs. AI can be helpful and is a great tool, but for this project, we will not use it without supervision or in an uncontrolled manner, for several reasons, including the following:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"Modifying a digital audio bus is a critical process when it comes to stability. As such, it must be approached responsibly. We need to understand how every part of the mod works to maintain control over it and ensure the highest possible audio quality and reliable operation of the modified interface."}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"The present is noisy, and the future is uncertain. AI seems to be here to stay, but the industry is changing so rapidly that it is worth taking a step back and approaching things calmly. Ultimately, we do this because we want to, and given how these devices are typically used, avoiding unnecessary haste is the most reasonable approach. There is no need to rush to deliver a new feature or merge a PR. Let's take our time."}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsx)(t.p,{children:"There is a special kind of joy in doing something simply for the pleasure of doing it. This might mean hand-coding a new feature, making design decisions, or reverse engineering a bus. If there is a process we can enjoy, such as implementing a new feature or reverse engineering a data bus, why delegate it to an automated process? If you enjoy solving Sudoku puzzles, you still solve them yourself, even though thousands of programs can do it in an instant."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"written by a software developer in crisis :)"})})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(6540);let a={},s=i.createContext(a);function o(e){let t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);